from .dispatcher.rmods.configuration import RmodConfiguration
from .dispatcher.rmods.connection import RmodConnection
from .dispatcher.uart_connector_factory import get_uart_connector
from .logger.logger import LogManager
from taf.hw.rmod_serial_interface import rmod_serial_interface
from taf.config.testline import RU
from copy import deepcopy
from pathlib import Path
import warnings


class DiagnosticCardFacade:
    """
    Facade for the Diagnostic Card.
    """

    def __init__(self):
        """
        Initialize the Diagnostic Card Facade.
        """
        self._rmod_init_config_parser = RmodConfiguration
        self._custom_setup = None
        self._rmod_connections = {}
        self._rsi = rmod_serial_interface()

    def prepare_log_directory_and_connection_setup(self, main_log_directory: str, connection_setup: str = None):
        """
        Setups the log directory and connection for the Diagnostic Card.
        :param main_log_directory: The main directory for logs from all RUs.
        :param connection_setup: Path to the custom setup YAML file for RUs connections.
        :return: None
        """
        self._setup(main_log_directory=main_log_directory)
        self._custom_setup = connection_setup

    def setup_connections(
        self,
        ru_config: RU,
        alias: str = None,
        log_to_console: bool = False,
        ignore_exceptions: bool = False,
        use_init_credentials: bool = False,
        **kwargs,
    ):
        """
        Setups the connections for all the RMODs connected to Diagnostic Cards.
        :param RU | list[RU] ru_config: RMOD configuration from the testline init file.
        :param str alias: Name of the RU connection. If None, the RU serial number will be used.
        :param bool log_to_console: Flag to log to console.
        :param bool ignore_exceptions: Flag to ignore exceptions during connection setup.
        :param bool use_init_credentials: Flag to use RMOD credentials from the testline init file.
                                          If set to True, then RMOD credentials will be read from the testline init file
                                          for the given RMOD family instead of using credentials from
                                          taf.config.testline or default credentials defined in the library.
                                          Defaults to False.
        :param kwargs: Additional parameters for RSI, PC host connection setup.
        :return: list - list of aliases. If single RU and alias provided, then returns a list with the alias.
        If default alias is used then list of serial numbers of connected RMODs is returned.
        """
        connected_rus_aliases = []
        setup_alias = None if isinstance(ru_config, list) else alias
        ru_config = ru_config if isinstance(ru_config, list) else [ru_config]

        for ru in ru_config:
            connected_rus_aliases.extend(
                self._setup_single_ru(
                    ru, setup_alias, log_to_console, ignore_exceptions, use_init_credentials, **kwargs
                )
            )

        return connected_rus_aliases

    def _setup_single_ru(self, ru, setup_alias, log_to_console, ignore_exceptions, use_init_credentials, **kwargs):
        """
        Helper method to set up a single RU.
        """
        try:
            ru_parameters = self._rmod_init_config_parser(ru, self._custom_setup)
            ru.lmi = ru_parameters.lmi
        except AttributeError:
            warnings.warn(message=f"Cannot retrieve rmod serial connection parameters for RU:{ru.serial_number}")
            return []

        return self._setup_uarts_for_ru(
            ru, ru_parameters, setup_alias, log_to_console, ignore_exceptions, use_init_credentials, **kwargs
        )

    def _setup_uarts_for_ru(
        self, ru, ru_parameters, setup_alias, log_to_console, ignore_exceptions, use_init_credentials, **kwargs
    ):
        """
        Helper method to set up UARTs for a single RU.
        """
        uart_aliases = []
        connected_rus_aliases = []

        for uart_config, sn_as_alias, uart_idx in self._split_ru_uarts(ru):
            alias = (setup_alias if uart_idx == 0 else f"{setup_alias}_{uart_idx}") if setup_alias else sn_as_alias
            uart_connector = get_uart_connector(uart_idx, self._rsi)

            try:
                self._initialize_uart_connection(
                    uart_connector,
                    ru,
                    ru_parameters,
                    alias,
                    log_to_console,
                    uart_config,
                    use_init_credentials,
                    **kwargs,
                )
                self._rmod_connections[alias] = uart_connector
                uart_aliases.append(alias)
                connected_rus_aliases.append(alias)
            except Exception as e:
                self._handle_uart_setup_exception(e, alias, uart_aliases, ignore_exceptions, uart_config)

        return connected_rus_aliases

    def _initialize_uart_connection(
        self, uart_connector, ru, ru_parameters, alias, log_to_console, uart_config, use_init_credentials, **kwargs
    ):
        """
        Helper method to initialize a UART connection.
        """
        logger_mngr = LogManager()
        logger, rmod_log_dir, log_prefix = logger_mngr.setup(
            alias=alias,
            log_dir=self.main_log_dir,
            rmod_type=ru.radio_type,
            serial_number=ru.serial_number,
            class_name=uart_connector.__class__.__name__,
            log_to_console=log_to_console,
        )
        connected_rmod_params = RmodConnection(
            ru_config=ru_parameters, logger=logger, log_dir=Path(rmod_log_dir), alias=alias, log_prefix=log_prefix
        )
        uart_connector.parameters = connected_rmod_params
        uart_connector.connect_new_rmod(uart_config, alias=alias, use_init_credentials=use_init_credentials, **kwargs)

    def _handle_uart_setup_exception(self, exception, alias, uart_aliases, ignore_exceptions, uart_config):
        """
        Helper method to handle exceptions during UART setup.
        """
        if not ignore_exceptions:
            warnings.warn(message=f"Failed to setup connection for {alias}: {exception}")
            for uart_alias in uart_aliases:
                self.disconnect(uart_alias)
            raise exception
        warnings.warn(message=f"Failed to setup connection for {uart_config}: {exception}")

    def send_command(self, alias: str, cmd: str, as_rfsw: bool = True):
        """
        Sends command to RMOD via serial console
        :param str alias: Name of the RU connection
        :param str cmd: Command to be sent to the RU console
        :param bool as_rfsw: If True, the command will be sent as RFSW user command. Defaults to True.
        :return: None
        """
        self.rmod_connections[alias].send_command(cmd=cmd, as_rfsw=as_rfsw)

    def execute_command(
        self, alias, cmd, elevated=False, wait_time: int = 30, write_output_to_logs=True, as_rfsw: bool = True
    ):
        """
        Executes command to RMOD via serial console and waits for the output
        :param str alias: Name of the RU connection
        :param str cmd: Command to be sent to the RU console
        :param bool elevated: If True, the command will be executed with elevated privileges
        :param int wait_time: Time to wait for the command to finish. Defaults to 30 seconds.
        :param bool write_output_to_logs: If True, the output will be written to the logs. Defaults to True.
        :param bool as_rfsw: If True, the command will be executed as RFSW user command. Defaults to True.
        :return: str - output of the command
        """
        return self.rmod_connections[alias].execute_command(
            cmd=cmd, elevated=elevated, wait_time=wait_time, write_output_to_logs=write_output_to_logs, as_rfsw=as_rfsw
        )

    def set_proxy_vm_address_and_username(self, alias: str, proxy_vm_address: str, proxy_vm_username: str = "ute"):
        """
        Sets the proxy VM address and username for the Rmod connection in the BTS+BTS setups,
        where direct SSH connection from local VM via SMOD to the RMOD is not possible.
        :param str alias: Name of the RU connection.
        :param str proxy_vm_address: Address of the proxy VM.
        :param str proxy_vm_username: Username for the proxy VM. Defaults to "ute", which is the default username
                                      for the VMs provided by UTE.
        :return: None
        """
        self.rmod_connections[alias].set_proxy_vm_address_and_username(
            proxy_vm_address=proxy_vm_address, proxy_vm_username=proxy_vm_username
        )

    def set_rmod_credentials(self, alias: str, password: str, username: str = "serviceuser"):
        """
        Sets the RMOD credentials for the RF Diagnostic Card library to use during connection setup
        or 'actSyncToRU' flag is in use and the 'serviceuser' account password is synchronized from SMOD to RMOD.

        :param str alias: Alias of the connection.
        :param str password: RMOD password.
        :param str username: RMOD username. Defaults to 'serviceuser'.
        :return: None
        """
        self.rmod_connections[alias].set_rmod_credentials(password=password, username=username)

    def get_rmod_ip(self, alias: str, wait_time: int = 120):
        """
        Returns the IP address of the Rmod connection with SMOD.
        :param str alias: Name of the RU connection.
        :param int wait_time: Time to wait for the IP address to be retrieved. Defaults to 120 seconds.
        :return: str/list[str]/None - IP address of the Rmod connection.
         List of IPs if RF Sharing configuration is used. None if connection with SMOD is not established.
        """
        return self.rmod_connections[alias].get_rmod_ip(wait_time=wait_time)

    def get_rmod_serial_number(self, alias: str):
        """
        Returns the serial number of the connected Rmod.
        :param str alias: Name of the RU connection.
        :return: Rmod serial number.
        """
        return self.rmod_connections[alias].rmod_serial_number

    def get_rmod_snapshot_path(self, alias: str):
        """
        Returns the path to the snapshot file.
        :param str alias: Name of the RU connection.
        :return: str - Path to the snapshot file in RMOD's ROM. None if snapshot was not collected or not saved to ROM.
        """
        return self.rmod_connections[alias].snapshot_path

    def download_log(self, alias: str, target_filepath: str):
        """
        Download the log from the RF Diagnostic Card.
        :param str alias: The alias of the Rmod connection.
        :param str target_filepath: The path to save the log on VM.
        :return: None
        """
        self.rmod_connections[alias].download_log(target_filepath=target_filepath)

    def download_snapshot(
        self, alias: str, target_path_on_vm=None, proxy_vm_address: str = None, proxy_vm_username: str = "ute"
    ):
        """
        Downloads the snapshot from the RF Diagnostic Card.
        :param str alias: Name of the RU connection.
        :param str target_path_on_vm: Path to save the snapshot on VM.
        :param str proxy_vm_address: Address of the proxy VM to use in BTS+BTS setups.
                                     If None, then the address set with the `set_proxy_vm_address_and_username`
                                     method will be used if set.
        :param str proxy_vm_username: Username for the proxy VM. Defaults to "ute", which is the default username
                                      for the VMs provided by UTE.
        :return: bool - True if the snapshot was downloaded successfully, False otherwise.
        """
        return self.rmod_connections[alias].download_snapshot(
            target_path_on_vm=target_path_on_vm, proxy_vm_address=proxy_vm_address, proxy_vm_username=proxy_vm_username
        )

    def create_file_preserving_rmod_flags(self, alias: str):
        """
        Creates a file preserving the current state of the Rmod flags.
        :param str alias: The alias of the Rmod connection.
        :return: None
        """
        self.rmod_connections[alias].create_file_preserving_rmod_flags()

    def take_snapshot(
        self,
        alias,
        target_path_on_vm: str = None,
        reset_rmod: bool = False,
        stop_and_fix: bool = False,
        skip_downloading: bool = False,
        timeout: int = 180,
        proxy_vm_address: str = None,
        proxy_vm_username: str = "ute",
    ):
        """
        Takes a snapshot of the Rmod connection.
        :param str alias: The alias of the Rmod connection.
        :param str target_path_on_vm: The path to save the snapshot on VM.
        :param bool reset_rmod: If True, the Rmod will be reset after taking the snapshot.
        :param bool stop_and_fix: If True, the procedure of reset will be skipped and the Rmod connection will be fixed.
        :param bool skip_downloading: If True, the snapshot will not be downloaded.
                                      Flag is ignored if snapshot is not saved in ROM.
        :param int timeout: The timeout for the snapshot operation. Defaults to 180 seconds.
        :param str/None proxy_vm_address: Address of the proxy VM to use in BTS+BTS setups.
                                          If None, then the address set with the
                                          `set_proxy_vm_address_and_username` method will be used if set.
        :param str proxy_vm_username: Username for the proxy VM. Defaults to "ute", which is the default username
                                      for the VMs provided by UTE.
        :return: bool - True if the snapshot was taken successfully, False otherwise.
        """
        return self.rmod_connections[alias].take_snapshot(
            target_path_on_vm=target_path_on_vm,
            reset_rmod=reset_rmod,
            stop_and_fix=stop_and_fix,
            skip_downloading=skip_downloading,
            timeout=timeout,
            proxy_vm_address=proxy_vm_address,
            proxy_vm_username=proxy_vm_username,
        )

    def switch_serial_to_node(self, alias: str, node: int):
        """
        Switches the serial connection to a specific node.
        :param str alias: The alias of the Rmod connection.
        :param str node: The node number to switch to.
        :return: bool - True if the switch was successful, False otherwise.
        """
        return self.rmod_connections[alias].switch_serial_to_node(node=node)

    def reset_rmod(self, alias: str, wait_time: int = 100):
        """
        Resets the Rmod connection.
        :param str alias: The alias of the Rmod connection.
        :param int wait_time: The time to wait for the reset to complete. Defaults to 100 seconds.
        :return: None
        """
        self.rmod_connections[alias].reset_rmod(wait_time=wait_time)

    def disconnect(self, alias: str):
        """
        Disconnects the Rmod connection.
        :param str alias: The alias of the Rmod connection.
        :return: None
        """
        self.rmod_connections[alias].disconnect()
        self.rmod_connections.pop(alias)

    def disconnect_all_rmods(self):
        """
        Disconnects all Rmod connections for known aliases.
        :return: None
        """
        for connection_alias in list(self.rmod_connections.keys()):
            self.disconnect(connection_alias)

    def disconnect_all_rmods_and_shutdown(self, host_connections=None):
        """
        Disconnects all Rmod connections and shuts down the host connections.
        :param str |  list[str] host_connections: Single or list of host connections to be shut down.
        Default is None, which means all known host connections will be shut down.
        :return:
        """
        self.disconnect_all_rmods()
        if host_connections is None:
            self._rsi.shutdown()
        else:
            host_connections = host_connections if isinstance(host_connections, list) else [host_connections]
            for host_connection in host_connections:
                self._rsi.shutdown(host_connection=host_connection)

    @property
    def rmod_connections(self):
        """
        Property keeping all connected RUs.
        :return: dict - all connected RUs.
        """
        return self._rmod_connections

    @staticmethod
    def _split_ru_uarts(ru_config):
        single_uart_ru_configs_with_alias = []
        for idx, uart in enumerate(ru_config.lmi.uart_mapping):
            ru_config_cp = deepcopy(ru_config)
            ru_config_cp.lmi.uart_mapping = [uart]
            alias = f"{ru_config.serial_number}_{idx}" if idx > 0 else ru_config.serial_number
            single_uart_ru_configs_with_alias.append((ru_config_cp, alias, idx))
        return single_uart_ru_configs_with_alias

    def _setup(self, main_log_directory: str, custom_setup: str = None):
        self.main_log_dir = LogManager.create_new_log_directory(main_log_directory)
        self._custom_setup = custom_setup
